import React from "react";
import "../Styles/Home.css";

export default function Home() {
    const [cars, setCars] = useState([]);
    const [loading, setLoading] = useState(true);
    const [searchParams, setSearchParams] = useSearchParams();
    const query = searchParams.get("q") || ""; 
    const [authorized, setAuthorized] = useState(true);
    const token = localStorage.getItem('authToken');


    useEffect(() => {
    const fetchNews = async () => {
      try {
        const response = await axios.get('https://855637b89fc9ec39.mokky.dev/news',{
          headers: { 
            Authorization: `Bearer ${token}`
          }
        });
        setNews(response.data);
        setAuthorized(true);


      } catch (error) {
        if (error.response && error.response.status === 401) {
          setAuthorized(false);
          console.log('Пользователь не авторизован. Пожалуйста, войдите в систему.');
        } else
        console.error('Ошибка загрузки новостей:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchNews();
  }, []);


    return (
        <main>
            <section className="hero-section">
                <div className="container">
                    <h1 className="display-4 fw-bold">
                        Аренда автомобилей премиум класса
                    </h1>
                    <p className="lead mt-3">
                        Выберите идеальный автомобиль для вашей поездки из нашего современного парка.<br />
                        Удобная аренда с гибкими условиями.
                    </p>
                </div>
            </section>

            <div className="container my-5">

                <div className="bg-white p-4 rounded shadow-sm mb-4">
                    <h4 className="mb-4">Фильтры</h4>
                    <div className="row g-3">

                        <div className="col-md-3 col-12">
                            <label className="form-label">Марка</label>
                            <select className="form-select">
                                <option>Все марки</option>
                                <option>BMW</option>
                                <option>Mercedes</option>
                                <option>Audi</option>
                                <option>Porsche</option>
                            </select>
                        </div>

                        <div className="col-md-2 col-6">
                            <label className="form-label">Мин. цена</label>
                            <input type="number" className="form-control" placeholder="От" />
                        </div>

                        <div className="col-md-2 col-6">
                            <label className="form-label">Макс. цена</label>
                            <input type="number" className="form-control" placeholder="До" />
                        </div>

                        <div className="col-md-3 col-12">
                            <label className="form-label">Доступность</label>
                            <select className="form-select">
                                <option>Все</option>
                                <option>Доступно</option>
                                <option>Занято</option>
                            </select>
                        </div>

                        <div className="col-md-2 col-12 d-flex align-items-end">
                            <button className="btn btn-primary w-100">Применить</button>
                        </div>
                    </div>
                </div>

                <p className="text-muted">
                    Найдено автомобилей: <strong id="car-count">8</strong>
                </p>

                <div 
                    className="row row-cols-1 row-cols-sm-2 row-cols-lg-3 row-cols-xl-4 g-4" 
                    id="cars-container"
                >

                    {/* Автомобиль */}
                    <div className="col">
                        <div 
                            className="card h-100 border-0 shadow-sm overflow-hidden position-relative"
                            style={{ borderRadius: "20px" }}
                        >

                            <div className="position-relative">
                                <img 
                                    src="https://images.unsplash.com/photo-1544636331-e26879cd4d9b?w=800&auto=format&fit=crop"
                                    className="card-img-top"
                                    alt="BMW X5"
                                    style={{ height: "220px", objectFit: "cover" }}
                                />

                                <span 
                                    className="position-absolute top-0 end-0 m-3 badge bg-success text-white px-3 py-2"
                                    style={{ borderRadius: "30px", fontSize: "0.9rem" }}
                                >
                                    Доступно
                                </span>
                            </div>

                            <div className="card-body p-4">
                                <h5 className="card-title mb-1 fw-bold">BMW X5</h5>

                                <p 
                                    className="text-muted mb-3"
                                    style={{ fontSize: "1.1rem" }}>
                                    2023
                                </p>

                                <div className="d-flex align-items-center gap-4 text-secondary mb-4">
                                    <span><i className="fas fa-cog me-1"></i> Automatic</span>
                                    <span><i className="fas fa-gas-pump me-1"></i> Diesel</span>
                                    <span><i className="fas fa-user-friends me-1"></i> 5</span>
                                </div>

                                <div className="d-flex justify-content-between align-items-center">
                                    <div>
                                        <div className="text-muted small">Цена</div>
                                        <div className="price_car" style={{fontSize:"1rem",color:"blue"}}>
                                            ₽18 000<small className="text-muted fs-6">/день</small>
                                        </div>
                                    </div>

                                    <a 
                                        href="#" 
                                        className="btn btn-primary rounded-pill px-4 py-2 shadow-sm"
                                        style={{ fontWeight: 600 }}
                                    >
                                        Подробнее
                                    </a>
                                </div>
                            </div>

                        </div>
                    </div>

                </div>
            </div>
        </main>
    );
}
